    <button @onclick="SaveNowAsync">Save now</button>
    <button @onclick="ClearAsync">Clear</button>
</div>

@if (_lastSavedAt is not null)
{
    <p>Last saved at @_lastSavedAt.Value.ToString("HH:mm:ss")</p>
}

@code {
    private string _content = string.Empty;
    private string _savedContent = string.Empty;
    private DateTime? _lastSavedAt;
    private NotepadInterop? _interop;
    private DotNetObjectReference<Notepad>? _dotNetRef;
    private Timer? _autoSaveTimer;
    private bool _beforeUnloadEnabled;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _interop = new NotepadInterop(JS);
            _dotNetRef = DotNetObjectReference.Create(this);
            await _interop.InitializeAsync(_dotNetRef);

            var saved = await _interop.LoadAsync();
            if (saved is not null)
            {
                _content = saved;
                _savedContent = saved;
                StateHasChanged();
            }

            _autoSaveTimer = new Timer(AutoSaveCallback, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
        }
    }

    private async void AutoSaveCallback(object? state)
    {
        await InvokeAsync(async () =>
        {
            if (_content != _savedContent)
            {
                await SaveContentAsync();
                StateHasChanged();
            }
        });
    }

    private async Task SaveNowAsync()
    {
        await SaveContentAsync();
    }

    private async Task SaveContentAsync()
    {
        if (_interop is null) return;

        await _interop.SaveAsync(_content);
        _savedContent = _content;
        _lastSavedAt = DateTime.Now;
        await UpdateBeforeUnloadAsync();
    }

    private async Task ClearAsync()
    {
        if (_interop is null) return;

        _content = string.Empty;
        _savedContent = string.Empty;
        _lastSavedAt = null;
        await _interop.ClearAsync();
        await UpdateBeforeUnloadAsync();
    }

    private async Task UpdateBeforeUnloadAsync()
    {
        if (_interop is null) return;

        var hasUnsaved = _content != _savedContent;
        var module = await GetModuleForBeforeUnloadAsync();

        if (hasUnsaved && !_beforeUnloadEnabled)
        {
            await module.InvokeVoidAsync("enableBeforeUnload");
            _beforeUnloadEnabled = true;
        }
        else if (!hasUnsaved && _beforeUnloadEnabled)
        {
            await module.InvokeVoidAsync("disableBeforeUnload");
            _beforeUnloadEnabled = false;
        }
    }

    private async Task<IJSObjectReference> GetModuleForBeforeUnloadAsync()
    {
        return await JS.InvokeAsync<IJSObjectReference>("import", NotepadInterop.ModulePath);
    }

    private async Task OnContentChanged(ChangeEventArgs e)
    {
        _content = e.Value?.ToString() ?? string.Empty;
        await UpdateBeforeUnloadAsync();
    }

    public async ValueTask DisposeAsync()
    {
        _autoSaveTimer?.Dispose();

        if (_interop is not null)
            await _interop.DisposeAsync();

        _dotNetRef?.Dispose();
    }
}

